import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"蹇","description":"高島易斷 - 蹇","frontmatter":{"title":"蹇","description":"高島易斷 - 蹇"},"headers":[],"relativePath":"classics/takashima/039.md","filePath":"classics/takashima/039.md"}'),i={name:"classics/takashima/039.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h2 id="蹇-1" tabindex="-1">蹇 <a class="header-anchor" href="#蹇-1" aria-label="Permalink to “蹇”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>蹇：利西南，不利東北，利見大人，貞吉。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《坎》位北，《艮》位東北，天氣由北而東，而南，而西；日月出於東，沒於西，天之行也。卦體內《艮》外《坎》，自東而北，逆天而行，是以為《蹇》。《蹇》自《睽》來，《艮》《坎》位在東北，《兌》《離》位在西南，就東北之本位，則難上加難，故“不利”，就西南，是《睽》位，則可以濟難，故“利”。且東北而西南為順天，順天者必利。“大人”，即《離》明繼照之大人也，明足濟《蹇》，故“利見”。道得其貞，吉無不利。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>山上有水，蹇，君子以反身修德。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>山上有水為《蹇》，《蹇》反卦《解》，《解》之《象》曰“雷雨作”。雷雨自上而降，雨降則山上之水必隨而降，則《蹇》可解矣。君子法之“以反身修德”，不憂其《蹇》之難解，惟慮其德之未修。《坎》為悔，有反悔之意焉；《艮》為慎，有德之義焉。孟子曰，“行有不得者，反求諸其身而已矣”，此之謂也。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：運當艱難，宜加奮勉，方可出險。</p><p>○　問戰徵：入山窮水，複雜之地，進退兩難，宜率六軍，戮力向西南進攻，方可獲利。</p><p>○　問功名：坎險《艮》止，功名有阻，返身加勉，五年後至上爻，《象》曰“利見大人，以從貴也”，成名可望。</p><p>○　問營商：水在山上，則水蓄而不流，有財不流通之象，營商者難之。</p><p>○　問家宅：此宅傍山，防有山上來水衝落，致損牆屋，宜改易其朝向，乃利。</p><p>○　問婚姻：山水本兩相為偶，山下水高則為失偶，故有《蹇》。不成則已，成亦必有反悔。</p><p>○　問疾病：《蹇》為足疾，涉水登山，必不能往行也。</p><p>○　問失物：宜反從身上尋之。</p><p>○　問訟事：宜自返而罷訟，吉。</p><p>○　問行人：被中途發水所阻，大有險難，他日空身可歸。</p><p>○　問六甲：生男。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>初爻居《艮》之下，當《蹇》之始，“往蹇”者，往就《蹇》地。在初去上《蹇》猶遠，可以不往，乃不避險阻，敢於犯難。在六爻之初，能首倡赴義，開“朋來”之先，聲聞嘉譽。《象傳》曰“宜待也”，以為輕身嘗試，徒博一時之譽，不如審機觀變，待時而動，斯得濟蹇之實功也。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：好運未來，宜謹守以待。</p><p>○　問戰徵：有險在前，未可進往，宜暫退守。</p><p>○　問營商：售賣之處，適有危，不可販貨前往，須暫時待價。</p><p>○　問功名：從軍效力，皆冒險犯難，獲邀獎賞，故曰“來譽”。</p><p>○　問家宅：地位險阻，遷居不利。</p><p>○　問疾病：在初起，不必急往求醫，宜退而自養。</p><p>○　問婚姻：不必急就，還宜待。吉。</p><p>○　問失物：緩之可得。</p><p>○　問六甲：生男。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某來，因一事進退未定，請卜以決之。筮得《蹇》之《既濟》。</p><p>斷曰：卦名曰《蹇》，《蹇》難也；卦爻在初，是初次遇難也。爻辭曰“往蹇”，其往就難地也；曰“來譽”，稱其勇於赴難也。而《象傳》則曰“宜待”，蓋謂輕身嘗試，不如待時而動也。玩釋爻意，其於臨難進退之機，歷歷明示。足下所問一事，為進退未定，得此爻而昭然如揭矣。神機發現，不爽毫釐，神妙如此。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>“王”指九五，“臣”指六二，二居下卦之中，上應九五，爻互重《坎》，故曰“蹇蹇”，謂其涉《蹇》以濟《蹇》，有鞠躬盡瘁之忱。諸爻皆言往，猶為國難而往赴之，二則直以國事為己事，犯其難而不顧也。《象傳》以“終無尤”釋之，謂其能致身事君，夫復何尤。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：目下氣運尷尬，險難重重，主一身勞碌。</p><p>○　問戰徵：防軍入險地，身被重圍，有龐士元落鳳坡之象。</p><p>○　問營商：為內地運貨，中途被水，有人財兩失之患。</p><p>○　問功名：為急公求名，名成而身莫保，邀身後之榮。</p><p>○　問家宅：此宅在艮山之中，向朝東北，險既重，不利。</p><p>○　問婚姻：二應五，主結貴親；防後日夫君有難，身命難保。</p><p>○　問訟事：兇。</p><p>○　問行人：兇。</p><p>○　問失物：終不可得。</p><p>○　問六甲：生男。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十三年某月，予過訪東京某紳士，互敘久別，主人曰：近因小兒為商務負債，日夕奔走措置，予甚憂慮。予曰：此等債務，憂亦無用，當善謀一置處之方，無已不如佔問一卦，以決可否。於是主人自執筮蓍，予代為祈禱，筮得《蹇》之《井》。</p><p>斷曰：《蹇》者多難之卦，二爻為下卦之主，是身任其難者也。令郎為商業負此鉅債，不能不前往處理，無如債累重重，一時終不能了。今佔得《蹇》二爻，爻辭曰“王臣蹇蹇，匪躬之故”，“蹇蹇”謂其事難而又難，“匪躬之故”，謂其債因商業而負，非一身之故也。玩前後爻象，三爻以“來返”為喜，知三爻不能相助為理；四爻曰“來連”，能與以為聯手；五爻為卦之主，是營商正主，或成訟則為裁判長官，曰“朋來”，謂招集債友，共相商議。《象》曰“中節”，節省也，謂節減債款以了事。上六則為局外之長者，前來居向調劑也。據此現宜從初爻之辭，暫為退待，以俟機會，毋須勞碌。某紳士深感《易》之妙，後果如佔所云。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>三爻居內卦之上，為《艮》之主，當上下之交，與《坎》為鄰。“往蹇”者，謂往赴五之“大蹇”。五以三陽當位，使之“來反”，以治其內。三本見險而止，喜退而不喜往也，其往也，為迫於諸爻，故同往；其返也，為得自全，故有喜。三動變為《比》，《比》二曰“比之自內”，故《象》以“內喜”釋之。</p><h2 id="九三佔" tabindex="-1">九三佔 <a class="header-anchor" href="#九三佔" aria-label="Permalink to “九三佔”">​</a></h2><p>○　問時運：運值多難，前進不利，不如退守。</p><p>○　問戰徵：有軍出》旋師之象。</p><p>○　問營商：有去而不來，販貨復回，轉銷內地之象。</p><p>○　問功名：為出使在外，改為內用。</p><p>○　問家宅：此宅後靠山，前臨水，初欲他遷，後復歸來，得以團聚為喜。</p><p>○　問婚姻：前欲他適，後得歸來，可喜。</p><p>○　問行人：即日來，喜。</p><p>○　問失物：失而復得。</p><p>○　問六甲：生男。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>明治二十三年，佔國運，筮得《蹇》之《比》。</p><p>斷曰：卦名曰《蹇》，《蹇》難也；爻曰“往蹇”，為往就蹇地；曰“來反”，為往而復返。《象》曰“內喜之也”，為喜其返而得以自全。詳釋爻辭，知國運值此多難，往而濟蹇，不如返而治內。至五爻，大君擅權，朋來相輔，而蹇可濟矣。則知以三濟內蹇，以五濟外蹇，相與有功也，喜可知矣。以爻象計之，應在二年之後。</p><p>明治元年四月，友人某來曰：餘近奉仕官某藩之命，發程有期，特來告別。觀其容貌威武，腰佩兩刀，猶是藩士舊狀，今際會風雲，有志維新者也。請佔前途氣運，筮得《蹇》之《比》。</p><p>斷曰：三為《艮》止之主，當上下之交，進退本多不決。其往也，固非所願，亦第隨人共往之耳；及其“來反”，焉得不中心喜之？爻辭之意如此。今足下因奉命將行，佔得此爻，度足下之意，或有亦因前途有難，不喜前往。餘勸足下，不妨準備前行，當有後命即來召回，欲令足下奉職於內也。後友人尚未起程，即命止行，留為內用。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四居上卦之首，比近於五，五所倚重，是為親近之臣。“連”者，謂君臣一體，如心腹股肱之相聯繫也。“往蹇來連”，謂三與上為正應，故與上同往，最為聯合，比初之往而有待，三之往而復反，較為得其實力也。《象》曰“當位實也”，四當位履正，《艮》為實，故曰“實”。上既比連尊爻，下又聯絡諸爻，得以實心實交以濟蹇難也。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：運多蹇險，以其能聯合眾心，得以濟險。</p><p>○　問戰徵：四爻陰柔，可知軍力單薄，以其能與眾軍同心同德，聯絡一氣，乃可出險。</p><p>○　問功名：“來連”者，有連升之象。</p><p>○　問營商：“來連”者，謂先後商客，皆相連而來；曰“當位實也”，“實”，充實，謂得贏滿也。</p><p>○　問家宅：此宅必與鄰屋比連，地位相當，家道殷實。</p><p>○　問婚姻：必是老親結親，重聯訂好，吉。</p><p>○　問疾病：此病必連綿已久，一時不愈。</p><p>○　問訟事：遲久可了。</p><p>○　問行人：流連在外，一時不歸。</p><p>○　問六甲：生男，想是孿胎。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>明治二十四年，有某友來，佔某國樞密院氣運，筮得《蹇》之《鹹》。</p><p>斷曰：四爻比連君位，是為親近之臣，所謂心腹股肱，與君一氣相聯者也，恰合樞密院之位。足下佔問某國，是外國也，故爻應在外卦。爻辭曰“往蹇，來連”，知某國近有內難外侮交作，樞密院諸臣，防有連累及禍者。諸爻皆曰“往蹇”，惟五與二不言往，五為大君，二為內臣，是身臨其難者也。樞密院本在內臣之位，諸爻以圖其濟蹇，曰“往蹇”者，或指出使於外而言。一時蹇難未平，氣運不佳，必待至上爻可以出蹇。</p><p>明治三十一年，佔眾議院氣運，筮得《蹇》之《鹹》。</p><p>斷曰：爻曰“來連”，有聯合眾議之象；《象》曰“當位”，謂得當議員之位。今政府以戰勝之後，受各邦之猜忌，將擴張兵備，預作濟蹇之圖，已呈出其議於議會，議員等聯絡私黨，不應政府之意，政府因之多難。上卦為《坎》，坎險也，下卦為《艮》，《艮》止也，合之謂《蹇》，以致政府號令有阻止而不能行也。今佔得四爻，四爻比近於五，知眾議員中必有深淺時艱，能體合至尊之意，折衷眾議之論說，以排解國家之困難，斯議可成，而蹇可濟矣。《象》曰“當位實也”，“實”謂能實濟其難，非從空言已也。當時議會自由改進，兩黨軋轢，議多不合，後自由黨迎合政府之意，與國民協會聯合，增稅之議乃決。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>就諸爻言則為“往”，就五爻言則為“來”，在諸爻則《蹇》猶小，在五爻則《蹇》獨大，蓋五爻合諸爻之蹇以為《蹇》，而獨當《蹇》之大者也，故曰“大蹇”。君臣以義合，朋友以情合，五略分言情，故喜其來而稱之謂“朋”。五盈滿當位，德足任人，故能使疏附後先，鹹來輔翼，得藉群才以濟“大蹇”。其濟也，雖出於君之威福，而諸臣要與有力焉。五動體《坤》，《坤》“西南得朋”，“蹇利西南”，故亦曰“朋”。《象》以“中節”釋之，謂五得位履中，不易其節，故卒得出蹇也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：厄運將退，漸得化危為安。</p><p>○　問戰徵：前既被圍，今幸得救兵齊來，得以一戰出圍。</p><p>○　問功名：位近至尊，足以匡濟，大榮，吉。</p><p>○　問營商：眾貨輻輳，一時難以脫售。</p><p>○　問家宅：地近禁衛，當衝擊疲難之區，車馬紛逐之會，不宜民居，可改作會館議院。</p><p>○　問疾病：此是危難大症，宜集眾醫會治，方可望愈。</p><p>○　問六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十年，佔某貴顯氣運，筮得《蹇》之《謙》。</p><p>斷曰：卦名曰《蹇》，爻曰“大蹇”，知《蹇》難重重，非一己之力，所能解脫。今某貴顯佔氣運，得第五爻，五爻為《蹇》之主，其《蹇》愈大，其濟愈難。幸某貴顯德望素著，眾心歸服，得藉朋儕相助，乃能戡平大難。目下正當協力匡濟之時，尚未出《蹇》，待一年後，《蹇》去《解》來，斯可平安無患。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>上爻居《蹇》之極，躬處局外，本為《蹇》難所不及，爻曰“往蹇”，蓋賢人君子，心切時艱，不敢以身不當位，置理亂於不聞也。“碩”，大也，“來碩”者，五得其相助為理，即以大任任之，如莘野渭濱之出而匡時者也，故曰“來碩”。《蹇》諸爻皆在蹇中，未嘗言吉，至上爻，其《蹇》已終，故稱“吉”。“大人”指五也，君臣同德，五爻以臣謂朋，上與五以君謂大人，蓋即《彖傳》所謂“利見大人，往有功也”。《象》以“志在內”釋“來碩”，謂上之應在三，故“志在內也”。以“從貴”釋“利見”，謂上之陰從陽，故曰“以從貴也”。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：現下大難已退，大運將來，可以出面求仕。</p><p>○　問戰徵：大兵已集，可以一戰，以出重圍。</p><p>○　問營商：眾商鹹來，貨價大漲，即此脫售可複本，亦可獲利。</p><p>○　問功名：文名大振，可以“利見大人”。</p><p>○　問家宅：此宅地位高大，災煞已退，吉曜照臨，且得貴人扶助。</p><p>○　問婚姻：主貴。</p><p>○　問訟事：須從大審院判結。</p><p>○　問六甲：生男。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>友人某來，請佔氣運，筮得《蹇》之《漸》。</p><p>斷曰：上爻居《蹇》之極，極則必變，將變《蹇》而成《解》，是大難將解之時也。今足下佔氣運，得上爻，爻辭曰“往蹇，來碩，吉，利見大人”，玩爻辭之意，謂“大蹇”已往，好運將來，吉無不利，且可往見大人，出而求仕，必得貴人提拔，仕途亨通。</p>',115)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
